def is_rotation(s1: str, s2: str) -> bool:
    # A rotation must have the same length and appear within s1 + s1.
    return len(s1) == len(s2) and s2 in (s1 + s1)

def find_missing_number(nums: list) -> int:
    # The range is 1..n where n is the largest value present in the list.
    # Using a set makes this robust to any duplicate values in nums.
    n = max(nums)
    present = set(nums)
    for num in range(1, n + 1):
        if num not in present:
            return num

