import math

def employees_with_salary_above(employees: list, min_salary: int) -> list:
    return [e["name"] for e in employees if e["salary"] >= min_salary]

def total_salary_in_department(employees: list, department: str) -> int:
    return sum(e["salary"] for e in employees if e["department"] == department)

def ceil_to_five_hundreds(num: int) -> int:
    return math.ceil(num / 500) * 500

def max_salary_after_increment_in_department(employees: list, department: str, inc_percent: int) -> int:
    salaries = [e["salary"] for e in employees if e["department"] == department]
    if not salaries:
        return 0
    best = max(s * (1 + inc_percent / 100) for s in salaries)
    return ceil_to_five_hundreds(best)
